// Generated by vibelang from db/migrations/0052_agent_views.ts; the migrate flow writes it again with each batch.
import { Effect } from "effect";
import { SqlClient } from "effect/sql";
// The agent's forms and generated views (decision 0004 §2 and §3, docs/features/views.md): the second slice of `views`.
// - `form`: `ui/form`'s template. `props` is `{ title, schema, submitLabel }`; `state` is `{ submitted: false }` until
//   the person submits, then `{ submitted: true, values, questionId }`, written with the submission's question.
// - `generated`: `ui/render`'s view. `code` is the renderer's TSX module, which only ChatApi's presentation realm runs;
//   `html` is what it rendered from `props` and `state`; `interactions` the module's declared events; `revision` counts
//   the state changes, so a move against an older state is refused. The device syncs every column but `code`.
// - `title` is a generated view's accessible name, and `size` where it shows first: `inline` or `full`.
// `view_moves` keeps each move a device made by the move's own id (its flow execution's) and the revision it made, in
// the move's transaction, so a move whose answer was lost and is sent again finds what it did rather than a stale board.
// A question asked from a view names it (`source`: `{ viewId, event }`) and carries the values sent with it (`data`),
// which the agent's turn reads beside the question's text. ChatApi bounds the values (16 KiB as JSON); jsonb prints them
// longer, so the table checks only their shape.
export default Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    yield* sql `
    DO $$
    DECLARE found record;
    BEGIN
      FOR found IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'views'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%template%'
      LOOP
        EXECUTE format('ALTER TABLE views DROP CONSTRAINT %I', found.conname);
      END LOOP;
    END $$`;
    yield* sql `
    ALTER TABLE views
      ADD COLUMN title text CHECK (char_length(title) BETWEEN 1 AND 120),
      ADD COLUMN size text NOT NULL DEFAULT 'inline' CHECK (size IN ('inline', 'full')),
      ADD COLUMN state jsonb,
      ADD COLUMN code text CHECK (octet_length(code) <= 65536),
      ADD COLUMN html text CHECK (octet_length(html) <= 262144),
      ADD COLUMN interactions jsonb CHECK (jsonb_typeof(interactions) = 'object'),
      ADD COLUMN revision integer NOT NULL DEFAULT 0 CHECK (revision >= 0),
      ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now()`;
    yield* sql `
    ALTER TABLE views ADD CONSTRAINT views_template_check CHECK (
      (template IN ('webpage', 'link', 'docs') AND state IS NULL AND code IS NULL AND html IS NULL)
      OR (template = 'form' AND state IS NOT NULL AND jsonb_typeof(state) = 'object' AND code IS NULL AND html IS NULL)
      OR (template = 'generated' AND title IS NOT NULL AND state IS NOT NULL AND code IS NOT NULL
        AND html IS NOT NULL AND interactions IS NOT NULL)
    )`;
    yield* sql `
    ALTER TABLE messages
      ADD COLUMN source jsonb CHECK (jsonb_typeof(source) = 'object'),
      ADD COLUMN data jsonb CHECK (jsonb_typeof(data) = 'object')`;
    yield* sql `ALTER TABLE messages ADD CONSTRAINT messages_source_question CHECK (source IS NULL OR role = 'user')`;
    yield* sql `
    CREATE TABLE view_moves (
      view_id uuid NOT NULL REFERENCES views (id) ON DELETE CASCADE,
      move_id text NOT NULL CHECK (char_length(move_id) BETWEEN 1 AND 256),
      revision integer NOT NULL,
      created_at timestamptz NOT NULL DEFAULT now(),
      PRIMARY KEY (view_id, move_id)
    )`;
});
